using System;
using System.Collections.Generic;
using Astrea.RunModifiers;
using FMODUnity;
using LittleLeo.Events;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "PlayerCurrentRunes", menuName = "Data/Battle/Runes/Player Current Runes")]
public class PlayerCurrentRunes : ScriptableObject
{
	public Rune[] Runes = new Rune[0];

	public Rune[] NonShuffledRunes = new Rune[0];

	[Header("Events")]
	[SerializeField]
	private VoidEvent OnUpdatePlayerCorruption;

	[Header("Omens")]
	[SerializeField]
	private CodexOfBurdensOmenData codexOfBurdensOmenData;

	[Header("SFX")]
	[SerializeField]
	private EventReference virtueActivatingDeactivatingSFX;

	[Header("Save System")]
	[SerializeField]
	private SaveSystem saveSystem;

	[Header("Battle Actions List")]
	[SerializeField]
	private BattleActionsList battleActionsList;

	[Header("Debug")]
	[SerializeField]
	private bool verbose;

	public List<int> usedRuneIndexes = new List<int>();

	public List<int> activeRuneIndexes = new List<int>();

	public List<int> refreshedRuneIndexes = new List<int>();

	[NonSerialized]
	public float currentPlayerCorruption;

	[NonSerialized]
	private Action codexOfBurdenAction;

	[NonSerialized]
	private bool playerHaveCodexOfBurden;

	[NonSerialized]
	private bool playerHaveFallenStar;

	private Character currentCharacter => ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter;

	public bool PlayerHaveFallenStar => playerHaveFallenStar;

	public void SetPlayerHaveFallenStar(bool value)
	{
		playerHaveFallenStar = value;
	}

	public void OnReset()
	{
		ResetUsedActiveAndRefreshedRunes();
		ResetCodexOfBurden();
		SetPlayerHaveFallenStar(value: false);
	}

	public void OnResetToStartRunState()
	{
		ResetRunesToStartRunState();
	}

	private void ResetRunesToStartRunState()
	{
		if (ReferenceSingleton<RunModifiersManager>.Instance.VirtuelessRunModifier != null)
		{
			SetRunes(ReferenceSingleton<RunModifiersManager>.Instance.VirtuelessRunModifier.GetCurrentRunesToNoVirtue());
			return;
		}
		if (!saveSystem.HasModVirtuesSetBattleSaveKey(currentCharacter.CharacterName))
		{
			SetDefaultOrModifiedRunes();
			return;
		}
		SaveSystem.ModVirtuesSetSave modVirtuesSetInfo = saveSystem.LoadModVirtuesSetBattle(currentCharacter.CharacterName);
		CharacterRunes.ModVirtueInfo modVirtueInfo = currentCharacter.CharacterRunes.CustomRunesList.Find((CharacterRunes.ModVirtueInfo _) => _.PublishedId == modVirtuesSetInfo.PublishedId);
		if (modVirtueInfo == null)
		{
			SetDefaultOrModifiedRunes();
			return;
		}
		CharacterRunes.VirtueSetInfo virtueSetInfo = modVirtueInfo.VirtuesSetInfosList.Find((CharacterRunes.VirtueSetInfo _) => _.SetId == modVirtuesSetInfo.SetId);
		if (virtueSetInfo == null)
		{
			SetDefaultOrModifiedRunes();
		}
		else
		{
			SetRunes(virtueSetInfo.Runes);
		}
	}

	private void SetDefaultOrModifiedRunes()
	{
		string characterName = ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter.CharacterName;
		if (!saveSystem.HasVirtuesRunCustomizationBattleSaveKey(characterName))
		{
			SetRunesToCurrentCharacterRunes();
			return;
		}
		List<RuneActionFaceSave> runeActionFaceSaves = saveSystem.LoadVirtuesRunCustomizationBattle(characterName).RuneActionFaceSaves;
		if (runeActionFaceSaves.Count == 0)
		{
			SetRunesToCurrentCharacterRunes();
			return;
		}
		Rune[] array = new Rune[7];
		for (int i = 0; i < runeActionFaceSaves.Count; i++)
		{
			RuneActionFaceSave runeActionFaceSave = runeActionFaceSaves[i];
			BattleAction battleAction = ((runeActionFaceSave.BattleActionName == null) ? null : battleActionsList.GetBattleAction(runeActionFaceSave.BattleActionName));
			Rune rune = new Rune(runeActionFaceSave.FaceName, runeActionFaceSave.ActionValue, battleAction, i);
			array[i] = rune;
		}
		SetRunes(array);
	}

	public void SetRunesToCurrentCharacterRunes()
	{
		SetRunes(currentCharacter.CharacterRunes.DefaultRunes);
	}

	public void SetRunes(Rune[] runesToSet)
	{
		Runes = new Rune[runesToSet.Length];
		NonShuffledRunes = new Rune[runesToSet.Length];
		for (int i = 0; i < runesToSet.Length; i++)
		{
			Rune rune = runesToSet[i];
			Runes[i] = new Rune(rune.FaceName, rune.ActionValue, rune.BattleAction, rune.index);
			NonShuffledRunes[i] = new Rune(rune.FaceName, rune.ActionValue, rune.BattleAction, rune.index);
		}
	}

	public void ResetUsedActiveAndRefreshedRunes()
	{
		usedRuneIndexes.Clear();
		activeRuneIndexes.Clear();
		refreshedRuneIndexes.Clear();
	}

	public void SetCodexOfBurdenOmenAction(bool value, Action codexOfBurdenAction)
	{
		this.codexOfBurdenAction = codexOfBurdenAction;
		playerHaveCodexOfBurden = value;
	}

	private void ResetCodexOfBurden()
	{
		codexOfBurdenAction = null;
		playerHaveCodexOfBurden = false;
	}

	public Rune[] GetCurrentCharacterRunes()
	{
		return currentCharacter.CharacterRunes.DefaultRunes;
	}

	[Button(null)]
	public bool IsAnyActionUnused()
	{
		for (int i = 0; i < Runes.Length; i++)
		{
			if (!(Runes[i].BattleAction == null))
			{
				if ((float)i > currentPlayerCorruption - 1f)
				{
					break;
				}
				if (!usedRuneIndexes.Contains(i))
				{
					("Player Corruption Action has at least 1 unused action\n" + Runes[i].BattleAction.name + " " + Runes[i].ActionValue).DebugLogIfVerbose(verbose);
					return true;
				}
			}
		}
		"All player corruption action used".DebugLogIfVerbose(verbose);
		return false;
	}

	[Button(null)]
	public bool IsAnyMustUseAction()
	{
		for (int i = 0; i < Runes.Length; i++)
		{
			if (!(Runes[i].BattleAction == null) && activeRuneIndexes.Contains(i) && !usedRuneIndexes.Contains(i) && CheckIfRuneContainsInteractions(Runes[i]))
			{
				("RUNES: activeRuneIndexes.Contains(i): " + activeRuneIndexes.Contains(i) + ", !usedRuneIndexes.Contains(i): " + !usedRuneIndexes.Contains(i)).DebugLogIfVerbose(verbose);
				("RUNES: Rune has at least 1 must use action with name " + Runes[i].BattleAction.name + " and index " + i).DebugLogIfVerbose(verbose);
				return true;
			}
		}
		"RUNES: Rune has no must use action".DebugLogIfVerbose(verbose);
		return false;
	}

	public bool IsAnyPlayableNonMustUseActions()
	{
		for (int i = 0; i < Runes.Length; i++)
		{
			if (!(Runes[i].BattleAction == null) && activeRuneIndexes.Contains(i) && !usedRuneIndexes.Contains(i) && !CheckIfRuneContainsInteractions(Runes[i]) && Runes[i].BattleAction.CheckConditionToBeCasted(playerHand: false, DiceOwnerEnum.PLAYER))
			{
				("RUNES: Rune has at least 1 Playable Non Must Use action with name " + Runes[i].BattleAction.name + " and index " + i).DebugLogIfVerbose(verbose);
				return true;
			}
		}
		"RUNES: Rune has no Playable Non Must Use action".DebugLogIfVerbose(verbose);
		return false;
	}

	private bool CheckIfRuneContainsInteractions(Rune rune)
	{
		return rune.BattleAction.BaseBattleActionData.HasMandatoryBattleActionInteractionEnum();
	}

	public void DisableAllRunes()
	{
		usedRuneIndexes.Clear();
		activeRuneIndexes.Clear();
		for (int i = 0; i < Runes.Length; i++)
		{
			if (!playerHaveFallenStar && refreshedRuneIndexes.Contains(i))
			{
				activeRuneIndexes.Add(i);
			}
			else
			{
				usedRuneIndexes.Add(i);
			}
		}
		OnUpdatePlayerCorruption.Raise();
		ReferenceSingleton<SFXHandler>.Instance.PlaySFX(virtueActivatingDeactivatingSFX);
	}

	public void SilencingAuraRemovedActivateRunes()
	{
		if (!playerHaveFallenStar)
		{
			usedRuneIndexes.Clear();
			OnUpdatePlayerCorruption.Raise();
			ReferenceSingleton<SFXHandler>.Instance.PlaySFX(virtueActivatingDeactivatingSFX);
		}
	}

	public void ActivateCodexOfBurdenOmen()
	{
		if (!playerHaveFallenStar && playerHaveCodexOfBurden && !codexOfBurdensOmenData.AlreadyUsed)
		{
			codexOfBurdenAction();
		}
	}

	public bool CheckCodexOfBurdenOmen()
	{
		if (playerHaveCodexOfBurden)
		{
			return codexOfBurdensOmenData.AlreadyUsed;
		}
		return false;
	}
}
